      // The query star.
      if (this.active) {
        const age = (performance.now() - this.active.born) / 1600;
        const grow = ease(Math.min(1, age));
        const [sx, sy] = t.apply([this.active.x, this.active.y]);
        if (age < 1) {
          ctx.globalAlpha = (1 - age) * 0.45;
          ctx.strokeStyle = pal.star;
          ctx.lineWidth = 1.5;
          ctx.beginPath();
          ctx.arc(sx, sy, 6 + age * 26, 0, Math.PI * 2);
