          if (!p) continue;
          const [hx, hy] = t.apply([p.px, p.py]);
          const local = (elapsed - pt.delayMs) / (this._particlesDuration * pt.speed);
          if (local <= 0 || local >= 1) continue;
          const dx = hx - sx;
          const dy = hy - sy;
          const len = Math.hypot(dx, dy) || 1;
          const nx = -dy / len;
          const ny = dx / len;
          const arc = Math.sin(Math.PI * local);
          const px = sx + dx * local + nx * pt.drift * arc;
          const py = sy + dy * local + ny * pt.drift * arc;
          ctx.globalAlpha = pt.alpha * arc;
          ctx.beginPath();
          ctx.arc(px, py, pt.size, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.globalAlpha = 1;
      }

      ctx.restore();
    },
  },
};
